import time, random, copy, numpy as np
from reference import Task
from scipy import sparse

def time_params(ncv, max_factor):
    task=Task();
    times=[]
    for seed in range(10):
        problem=task.generate_problem(n=300, random_seed=seed)
        A=problem['matrix']; N=A.shape[0]
        start=time.perf_counter()
        sparse.linalg.eigs(A,k=5,v0=np.ones(N),ncv=ncv,maxiter=N*max_factor)
        times.append(time.perf_counter()-start)
    return sum(times)/len(times)

for ncv in [20,30,40,50]:
